CREATE INDEX polls_geom_idx ON polls USING GIST (geom);

SELECT o.id, near.id AS poll_id, near.dist_m
FROM origins o
CROSS JOIN LATERAL (
  SELECT p.id, ST_Distance(o.geom, p.geom) AS dist_m
  FROM polls p
  WHERE ST_DWithin(o.geom, p.geom, 500)
  ORDER BY o.geom <-> p.geom
  LIMIT 1
) near;

